"""Detailed explanations with diagrams: HLD questions, part 3."""
from sd_x_util import X, P, H, AN, KEY, FLOW, SEQ, NOTE, ER, TABLE, CALC, BARS, CODE, UML, STATE

X("ticketmaster-hld",
  P("""**What the system does.** Browse events, pick seats on a seat map, **hold** them for ~10 minutes while paying, then book. Normal days are quiet; a big concert release brings **a million people in the first minute for 50,000 seats**. Correctness (never sell a seat twice) and surviving that spike are the whole problem."""),
  AN("A theatre box office on release day: a queue outside lets people in at a steady pace (virtual waiting room); inside, the clerk puts a 'reserved for you' card on the seats you point at (hold with expiry) and only one card fits on a seat (conditional update)."),
  CALC("The release-day spike", [("Users arriving in the first minute", "u = 1e6", ""), ("Arrival rate", "u / 60", "/s"), ("Seats", "s = 50e3", ""), ("Users per seat", "u / s", ""),
                                  ("Admission rate the booking DB can take (assume)", "2000", "/s", "waiting room admits ~this many; the rest wait their turn")]),
  STATE("A seat's life", [["AVAILABLE"], ["HELD (hold_id, expires)"], ["BOOKED"]],
        [["AVAILABLE", "HELD (hold_id, expires)", "hold: conditional UPDATE wins"], ["HELD (hold_id, expires)", "AVAILABLE", "expired / payment failed"], ["HELD (hold_id, expires)", "BOOKED", "payment success"]]),
  SEQ("Holding and buying two seats", ["User", "Waiting room", "Booking service", "Seats DB", "Payment"],
      [["User", "Waiting room", "join queue", "", "The CDN serves a static waiting page and issues a signed token when it's your turn: the booking service only sees admitted users."],
       ["Waiting room", "User", "admitted (token)", "r"], ["User", "Booking service", "hold seats A9, A10"],
       ["Booking service", "Seats DB", "UPDATE seats SET status='HELD', hold_id=h, expires=now()+10m WHERE show=? AND seat IN (A9,A10) AND status='AVAILABLE'", "", "Atomic check-and-set in one statement; 'rows updated' must equal 2, otherwise roll back and tell the user the seats were taken."],
       ["Seats DB", "Booking service", "2 rows updated", "r"], ["Booking service", "User", "held until 10:10", "r"],
       ["User", "Payment", "pay (idempotency key = h)"], ["Payment", "Booking service", "success webhook"],
       ["Booking service", "Seats DB", "UPDATE … SET status='BOOKED' WHERE hold_id=h AND status='HELD' AND expires > now()", "", "If the hold already expired the payment is refunded automatically."]]),
  ER("Data model", [("seats", "PostgreSQL (partitioned by show)", [("show_id", "bigint", "PK"), ("seat_id", "varchar", "PK"), ("status", "AVAILABLE/HELD/BOOKED", ""), ("hold_id", "uuid", "IDX"), ("hold_expires_at", "timestamptz", "IDX"), ("price_tier", "", "")], ""),
                    ("bookings", "PostgreSQL", [("booking_id", "uuid", "PK"), ("hold_id", "uuid", "UNIQUE"), ("user_id", "", ""), ("amount_paise", "bigint", ""), ("status", "", "")], "")]),
  TABLE("Locking options", ["Option", "How", "Trade-off"], [["conditional update (chosen)", "WHERE status='AVAILABLE'", "simple, no long locks"], ["pessimistic", "SELECT … FOR UPDATE then UPDATE", "locks held across round trips"],
        ["optimistic", "version column, retry on mismatch", "many retries under contention"], ["Redis SET NX EX", "seat key per hold", "absorbs extreme spikes; DB stays the source of truth"]]))

X("ecommerce-hld",
  P("""**What the system does.** Browse and search a catalogue, keep a cart, and **check out**: reserve stock, take payment, create the order, ship it. Browsing is huge and read-only (cache it aggressively); checkout is small but must be correct across several services (inventory, payment, orders) with **no distributed transaction**, so we use a **saga**."""),
  AN("A checkout saga is like booking a holiday: reserve the flight, then the hotel, then pay. If the hotel is full you cancel the flight reservation (a compensating step). Nobody locks the airline and hotel together; each step has an undo."),
  CALC("Sizing", [("Orders per second (average)", "5e6 / 86400", "/s"), ("Sale peak", "1000", "/s"), ("Product page views", "100e3", "/s", "served mostly from CDN + caches")]),
  SEQ("Checkout saga (orchestrated)", ["Shopper", "Checkout orchestrator", "Inventory", "Payment", "Order service", "Kafka"],
      [["Shopper", "Checkout orchestrator", "place order (cart, address, idemKey)", "", "The idempotency key makes a double-click or retry safe."],
       ["Checkout orchestrator", "Inventory", "reserve SKU×qty (expires 15 min)", "", "UPDATE stock SET reserved = reserved + q WHERE sku=? AND available - reserved >= q: no overselling."],
       ["Inventory", "Checkout orchestrator", "reserved", "r"], ["Checkout orchestrator", "Payment", "authorise ₹ (idemKey)"], ["Payment", "Checkout orchestrator", "authorised", "r"],
       ["Checkout orchestrator", "Order service", "create order CONFIRMED"], ["Checkout orchestrator", "Inventory", "commit reservation"],
       ["Order service", "Kafka", "OrderPlaced (via outbox)", "a", "Shipping, notifications, analytics react asynchronously."],
       NOTE(["Shopper", "Kafka"], "If payment fails: orchestrator calls Inventory.release (compensation) and the order is FAILED")]),
  STATE("Order states", [["CREATED"], ["PAYMENT_PENDING", "FAILED"], ["CONFIRMED"], ["SHIPPED", "CANCELLED"], ["DELIVERED"]],
        [["CREATED", "PAYMENT_PENDING", "stock reserved"], ["CREATED", "FAILED", "out of stock"], ["PAYMENT_PENDING", "CONFIRMED", "paid"], ["PAYMENT_PENDING", "FAILED", "payment failed → release stock"], ["CONFIRMED", "SHIPPED", ""], ["CONFIRMED", "CANCELLED", "refund"], ["SHIPPED", "DELIVERED", ""]]),
  TABLE("Each service picks its own trade-off", ["Service", "Store", "Consistency", "Why"],
        [["Catalogue", "document DB + Elasticsearch + CDN", "eventual", "read-mostly, rich documents"], ["Cart", "DynamoDB / Redis", "available (AP)", "'add to cart' must always work"],
         ["Inventory", "SQL", "strong per SKU", "no overselling"], ["Orders / payments", "SQL", "strong", "money"], ["Events", "Kafka + outbox", "at-least-once", "reliable hand-offs"]]))

X("payment-hld",
  P("""**What the system does.** Takes money from customers through payment providers (cards, UPI, netbanking) and pays merchants. Volume is modest (~120 payments/s) but **correctness is everything**: never charge twice, never lose a payment whose result is unknown, and keep books that always balance. Three tools do the work: **idempotency keys**, a **state machine** with conditional transitions, and a **double-entry ledger**."""),
  AN("A careful accountant: every request comes with a receipt number (idempotency key) so the same request is never processed twice; every payment moves through stamped stages; and every rupee moved is written twice, once as money leaving one account and once as money arriving in another, so the books always sum to zero."),
  STATE("Payment state machine", [["CREATED"], ["PENDING"], ["SUCCEEDED", "FAILED"], ["REFUNDED"]],
        [["CREATED", "PENDING", "sent to PSP"], ["PENDING", "SUCCEEDED", "webhook / poll: success"], ["PENDING", "FAILED", "declined / expired"], ["SUCCEEDED", "REFUNDED", "refund"]],
        "Every transition is `UPDATE payments SET status=new WHERE id=? AND status=old`: if a webhook and the poller race, only one wins."),
  SEQ("Charging ₹499 safely", ["Order service", "Payment service", "Payments DB", "Risk", "PSP / bank", "Ledger"],
      [["Order service", "Payment service", "POST /payments {order 77, ₹499, Idempotency-Key k1}"], ["Payment service", "Payments DB", "INSERT … idempotency_key = k1 (UNIQUE)", "", "A retry with k1 hits the unique constraint → return the stored result instead of charging again."],
       ["Payment service", "Risk", "score"], ["Payment service", "PSP / bank", "charge (our payment id as THEIR idempotency key)", "", "Idempotency at every hop: our retry to the PSP can't double charge either."],
       ["PSP / bank", "Payment service", "timeout?!", "r", "Unknown outcome: never just retry blindly. Mark PENDING and **query** the PSP for status."],
       ["PSP / bank", "Payment service", "webhook: succeeded (signed)", "", "Verify the signature, dedupe by event id."],
       ["Payment service", "Payments DB", "PENDING → SUCCEEDED (conditional)"], ["Payment service", "Ledger", "debit customer_clearing ₹499 / credit merchant_payable ₹499", "", "Written in the same DB transaction as the state change; ledger rows are never updated or deleted."]]),
  TABLE("Double-entry ledger for one payment (₹)", ["Entry", "Account", "Debit", "Credit"],
        [["1", "PSP receivable", "499.00", ""], ["1", "Merchant payable", "", "489.02"], ["1", "Fee revenue (2%)", "", "9.98"], ["", "**Sum**", "**499.00**", "**499.00**"]],
        "Balances are sums of entries, so they can always be recomputed and audited."),
  TABLE("Failure handling", ["Situation", "Handling"], [["client retries", "same idempotency key → same response"], ["PSP timeout", "PENDING + status query; reconciliation catches the rest"],
        ["webhook lost", "poller for PENDING payments older than N minutes"], ["DB commit failed after PSP success", "nightly reconciliation against PSP settlement files"], ["card data", "never stored: PSP tokens (keeps PCI scope small)"]]))

X("hotel-hld",
  P("""**What the system does.** Guests search hotels/homes by place and dates, then book a stay of several nights. A booking succeeds only if **every night** has a room available, and two guests must never get the last room on the same night. Modelling inventory as **one row per (property, date)** turns a tricky interval problem into simple conditional updates."""),
  AN("A wall calendar per hotel where each day shows 'rooms left'. Booking 3 nights means crossing off one room on 3 days, all at once; if any day is at zero, nothing is crossed off."),
  ER("Inventory per night", [("room_inventory", "PostgreSQL (sharded by hotel)", [("hotel_id", "bigint", "PK"), ("room_type", "varchar", "PK"), ("date", "date", "PK"), ("total", "int", ""), ("reserved", "int", "CHECK ≤ total")], "One row per night: 365 rows per room type per year."),
                             ("reservations", "PostgreSQL", [("id", "uuid", "PK"), ("hotel_id, room_type", "", ""), ("check_in, check_out", "date", ""), ("guest_id", "", ""), ("status", "HELD/CONFIRMED/CANCELLED", ""), ("idempotency_key", "", "UNIQUE")], "")]),
  SEQ("Book 3 nights (20–23 Dec)", ["Guest", "Reservation service", "Inventory DB", "Payment"],
      [["Guest", "Reservation service", "reserve (hotel 7, deluxe, 20→23 Dec, idemKey)"], ["Reservation service", "Inventory DB", "BEGIN"],
       ["Reservation service", "Inventory DB", "UPDATE room_inventory SET reserved = reserved + 1 WHERE hotel=7 AND type='deluxe' AND date IN (20, 21, 22 Dec) AND reserved < total", "", "Check-out day (23) isn't a night you sleep, so it isn't reserved."],
       ["Inventory DB", "Reservation service", "3 rows updated?", "r", "If fewer than 3 → ROLLBACK: some night is full, nothing changes."],
       ["Reservation service", "Inventory DB", "INSERT reservation HELD; COMMIT"], ["Reservation service", "Payment", "charge"], ["Payment", "Reservation service", "ok → CONFIRMED (or release on failure / expiry)", "r"]]),
  TABLE("Search vs booking", ["", "Search", "Booking"], [["store", "Elasticsearch (geo + amenities + denormalised availability)", "SQL rows per night"], ["freshness", "seconds behind (CDC)", "exact"],
        ["load", "~10k QPS", "~60/s"], ["rule", "may show a room that just sold", "always re-checked here"]]))

X("metrics-hld",
  P("""**What the system does.** Collects numbers (CPU %, request latency, error counts) from every server every few seconds, stores them as **time series**, draws dashboards and fires alerts. At **10 million data points per second** the design is about write throughput, compression and cheap long-term storage."""),
  AN("A weather network: thousands of stations report temperature every 10 seconds. You keep recent readings in detail, older ones as hourly averages, and an alarm rings when a reading stays over a threshold for 5 minutes, not on a single spike."),
  CALC("Sizing", [("Points per second", "p = 100e3 * 1000 / 10", "/s"), ("Raw (16 B/point) per day", "p * 16 * 86400", "B"), ("Gorilla-compressed (~1.4 B/point) per day", "p * 1.4 * 86400", "B"),
                  ("Active series (100k hosts × 1,000 metrics)", "100e3 * 1000", "")]),
  FLOW("Write and alert paths", [["Agents on hosts"], ["Ingestion gateways"], ["q:Kafka (by series)"], ["TSDB writers", "Stream aggregator (rollups)", "Alert evaluator"], ["db:Time-series store (hot)", "db:Object storage (cold)", "x:Notifier (PagerDuty/Slack)"]],
       [["Agents on hosts", "Ingestion gateways", "batched"], ["Ingestion gateways", "Kafka (by series)"], ["Kafka (by series)", "TSDB writers"], ["Kafka (by series)", "Stream aggregator (rollups)"], ["Kafka (by series)", "Alert evaluator"],
        ["TSDB writers", "Time-series store (hot)", "2-h blocks"], ["Stream aggregator (rollups)", "Object storage (cold)", "1-min / 1-h"], ["Alert evaluator", "Notifier (PagerDuty/Slack)", "firing"]]),
  TABLE("Why Gorilla compression works (real-ish CPU series)", ["Timestamp", "Δ", "ΔΔ (stored)", "Value", "XOR with previous"],
        [["10:00:00", "", "first: full", "41.5", "first: full"], ["10:00:10", "10", "10", "41.5", "0 → 1 bit"], ["10:00:20", "10", "0 → 1 bit", "41.7", "few bits differ"], ["10:00:30", "10", "0 → 1 bit", "41.7", "0 → 1 bit"]],
        "Regular intervals make delta-of-delta zero, and slowly changing values make XORs mostly zero: ~1.4 bytes per point instead of 16."),
  STATE("Alert life cycle", [["OK"], ["PENDING"], ["FIRING"], ["RESOLVED"]],
        [["OK", "PENDING", "rule true"], ["PENDING", "OK", "rule false before 'for: 5m'"], ["PENDING", "FIRING", "true for 5 min → notify"], ["FIRING", "RESOLVED", "rule false"], ["RESOLVED", "OK", ""]]),
  TABLE("Pitfalls", ["Pitfall", "Fix"], [["high-cardinality tags (user_id) explode series count", "per-tenant series limits; put ids in logs/traces instead"], ["averaging p99s across hosts", "store histograms/sketches and merge them"],
                                       ["alerts depend on the dashboard DB", "separate evaluation path; meta-monitoring of the monitor"], ["keeping 10-s data forever", "downsample: 10 s for 2 weeks, 1 min for 3 months, 1 h for years"]]))

X("logging-hld",
  P("""**What the system does.** Gathers logs from every server into one place where engineers can search them in seconds during an incident, keeps them cheap for a year, and never lets a logging problem take down the applications. The usual shape: local agent → **Kafka buffer** → processors → **search index for recent days** + **object storage archive**."""),
  AN("A shipping port: lorries (agents) drop containers at a huge yard (Kafka) even when the cranes (indexers) are slow or broken; cranes load ships at their own pace. Recent cargo stays on the quay for quick access (search index); older cargo goes to a cheap warehouse (S3)."),
  CALC("Sizing", [("Log volume per day", "v = 10e3 * 1e9", "B"), ("Ingest rate", "v / 86400", "B/s"), ("7 days hot in the search cluster (×1.5 index overhead, ×2 replicas)", "v * 7 * 1.5 * 2", "B"),
                  ("1 year archived in S3 (compressed ~10×)", "v * 365 / 10", "B")]),
  SEQ("From a log line to a search result", ["App", "Fluent Bit agent", "Kafka", "Processor", "Search cluster", "S3 archive", "Engineer"],
      [["App", "Fluent Bit agent", "JSON line to stdout {level, msg, trace_id, user}", "", "Structured logs with a trace/request id make correlation possible."],
       ["Fluent Bit agent", "Kafka", "batched, compressed", "a", "The agent buffers on disk if Kafka is unreachable; the app never blocks on logging."],
       ["Processor", "Kafka", "consume"], ["Processor", "Processor", "parse, enrich (service, region), redact PII (cards, emails)"],
       ["Processor", "Search cluster", "index into logs-2026.11.26", "", "Daily indices: deleting old data = dropping a whole index (cheap)."], ["Processor", "S3 archive", "write compressed Parquet/gzip"],
       ["Engineer", "Search cluster", "trace_id:abc AND level:ERROR (last 1 h)"]]),
  TABLE("Cost controls", ["Lever", "Effect"], [["index only key fields; keep the message as stored text", "smaller indices"], ["Loki-style: index labels only, grep chunks", "much cheaper, slower full-text"],
                                             ["sample DEBUG logs", "less volume"], ["hot 7 days / warm 30 / cold S3 1 year", "pay for speed only where needed"]]))

X("topk-hld",
  P("""**What the system does.** Answers 'what are the 10 most viewed videos (or hashtags) in the last hour/day?' continuously, over a stream of ~1 billion events a day that can spike to a million per second. Exact counting of every item is possible when partitioned well; when memory is tight, **Count-Min Sketch + a heap** gives a close answer in fixed memory."""),
  AN("Counting votes on election night: each polling station (partition) counts its own ballots and reports its local leaders every few minutes; headquarters merges the reports into the national top 10. Partitioning by candidate means each candidate's votes are counted in one place, so the merge is exact."),
  CALC("Sizing", [("Average events per second", "1e9 / 86400", "/s"), ("Peak", "1e6", "/s"), ("Exact counts for 100 M distinct items (×16 B)", "100e6 * 16", "B", "fits across a few workers when partitioned"),
                  ("Count-Min Sketch 4 × 2^20 counters × 4 B", "4 * 2 ** 20 * 4", "B", "fixed size, any number of items")]),
  FLOW("Streaming pipeline", [["x:View/click events"], ["q:Kafka (partitioned by item)"], ["Stream workers: per-partition counts + Count-Min"], ["Merger: global top-K per window"], ["c:Top-K store (Redis)", "Batch job (exact daily)"], ["API"]],
       [["View/click events", "Kafka (partitioned by item)"], ["Kafka (partitioned by item)", "Stream workers: per-partition counts + Count-Min"], ["Stream workers: per-partition counts + Count-Min", "Merger: global top-K per window", "local top-K / min"],
        ["Merger: global top-K per window", "Top-K store (Redis)"], ["Top-K store (Redis)", "API"], ["Batch job (exact daily)", "Top-K store (Redis)", "corrects daily list"]]),
  TABLE("Sliding 1-hour window with 60 one-minute buckets", ["Minute", "Bucket counts for video V", "Window total"],
        [["10:00", "[…, 10:00 = 1,200]", "sum of the last 60 buckets"], ["10:01", "add bucket 10:01 = 900, drop 09:01", "total += 900 − count(09:01)"], ["…", "", "O(1) per minute per item"]],
        "Sliding = add the newest bucket, subtract the one that falls out."),
  TABLE("Count-Min Sketch in one picture", ["Step", "What happens"], [["update(item)", "hash the item with d hash functions; +1 in one cell of each of the d rows"],
        ["estimate(item)", "min over the d cells (collisions only ever add, so min is the least inflated)"], ["error", "overestimates by at most ε·N with probability 1 − δ, using (e/ε) × ln(1/δ) counters"],
        ["top-K", "keep a min-heap of K items with the highest estimates as events arrive"]]))
